@MethodSource("data")
public void visibleWhere(final Where where, final Where whereContext, final boolean expectedVisibility) {
    Mockito.when(mockHiddenFacet.where()).thenReturn(where);
    Mockito.when(mockObjectAssociation.streamFacets()).thenReturn(List.<Facet>of(mockHiddenFacet).stream());
    final Predicate<ObjectAssociation> predicate = association -> {
        final List<Facet> facets = association.streamFacets().filter(facet -> facet instanceof WhereValueFacet && facet instanceof HiddenFacet).collect(Collectors.toList());
        for (Facet facet : facets) {
            final WhereValueFacet wawF = (WhereValueFacet) facet;
            if (wawF.where().includes(whereContext)) {
                return false;
            }
        }
        return true;
    };
    assertThat(predicate.test(mockObjectAssociation), is(expectedVisibility));
}

